function H(r){var n=Fraction(1).sub(Fraction(4).mul(r[0]));return[Fraction(-2).div(n),Fraction(1).div(n),Fraction(1).div(n),Fraction(-2).mul(r[0]).div(n)]}function grad(r){return[Fraction(r[0]).mul(r[0]).add(r[1]),Fraction(2).mul(r[1]).add(r[0])]}function matrMult(r,n){return[Fraction(r[0]).mul(n[0]).add(Fraction(r[1]).mul(n[1])),Fraction(r[2]).mul(n[0]).add(Fraction(r[3]).mul(n[1]))]}function vecSub(r,n){return[Fraction(r[0]).sub(n[0]),Fraction(r[1]).sub(n[1])]}function run(r){var n=H(r);for(var a in n);var i=grad(r);for(var a in i);var t=matrMult(n,i);for(var a in t);var u=vecSub(r,t);return u}const Fraction=require("fraction.js");for(var v=[3,2],i=0;i<15;i++)v=run(v,i);